async function stressModal() {
  for (let i = 0; i < 30; i++) {
    openModal(fetch(`/api/items/${i}`));
    await new Promise((r) => setTimeout(r, 50));
    closeModal(); // bug: listeners not removed
  }
}
// Take heap snapshot before and after stressModal

process.on("SIGUSR2", () => {
  const v8 = require("node:v8");
  const path = `/tmp/heap-${Date.now()}.heapsnapshot`;
  v8.writeHeapSnapshot(path);
  console.log("wrote", path);
});

